import boto3
from typing import Dict, Optional

def get_text(result, blocks_map: Dict[str, dict]) -> str:
    text = ''
    if 'Relationships' in result:
        for relationship in result['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    word = blocks_map[child_id]
                    if word['BlockType'] == 'WORD':
                        if 'Text' in word:
                            text += word['Text'] + ' '
                    if word['BlockType'] == 'SELECTION_ELEMENT':
                        if word['SelectionStatus'] == 'SELECTED':
                            text += 'X '
                        else:
                            text += '  '
    return text.strip()

def find_value_block(key_block: dict, value_map: Dict[str, dict]) -> Optional[dict]:
    for relationship in key_block.get('Relationships', []):
        if relationship['Type'] == 'VALUE':
            for value_id in relationship['Ids']:
                return value_map.get(value_id)
    return None

def extract_kv_pairs(document_path: str) -> Dict[str, str]:
    with open(document_path, 'rb') as file:
        image_bytes = file.read()

    textract = boto3.client('textract')

    response = textract.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']
    blocks_map = {}
    key_map = {}
    value_map = {}

    for block in blocks:
        blocks_map[block['Id']] = block
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_map[block['Id']] = block
            if 'VALUE' in block['EntityTypes']:
                value_map[block['Id']] = block

    key_value_pairs = {}
    for key_id, key_block in key_map.items():
        value_block = find_value_block(key_block, value_map)
        if value_block:
            key_text = get_text(key_block, blocks_map)
            val_text = get_text(value_block, blocks_map)
            key_value_pairs[key_text] = val_text

    return key_value_pairs
